import React from 'react';
import { useInstitution } from '../../context/InstitutionContext';
import ReportTable from './ReportTable';
import ReportExport from './ReportExport';

const getGeneratedByLabel = () => {
  try {
    const raw = localStorage.getItem('scoms_admin_user');
    if (!raw) return 'Institute Admin';
    const user = JSON.parse(raw);
    return user.email || 'Institute Admin';
  } catch {
    return 'Institute Admin';
  }
};

/** The generic Report Preview screen: header (report, institution, generated by/at,
 * applied filters), the dynamic table, then export actions — for every report, always. */
export const ReportPreview = ({ result, definition, filters, onGenerateAgain }) => {
  const { institution } = useInstitution();

  const appliedFilters = Object.entries(filters || {}).filter(([, v]) => v !== '' && v !== undefined && v !== null);

  return (
    <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-xl p-5 print-container space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3 border-b border-slate-200 dark:border-slate-800 pb-4">
        <div className="flex items-start gap-3 min-w-0">
          {institution?.logo ? (
            <img src={institution.logo} alt={institution.name} className="w-11 h-11 rounded-lg object-cover border border-slate-200 dark:border-slate-700 shrink-0" />
          ) : (
            <div className="w-11 h-11 rounded-lg bg-indigo-600 text-white flex items-center justify-center font-black text-sm shrink-0">
              {institution?.code?.[0] || institution?.name?.[0] || 'S'}
            </div>
          )}
          <div className="min-w-0">
            <p className="text-[10px] font-bold text-indigo-600 uppercase tracking-wider truncate">{institution?.name || 'SCOMS'}</p>
            <h3 className="text-base font-bold text-slate-900 dark:text-white">{result.report.name}</h3>
            <p className="text-[11px] text-slate-500 mt-0.5">
              Generated {new Date(result.generatedAt).toLocaleString()} by {getGeneratedByLabel()}
            </p>
            {appliedFilters.length > 0 && (
              <p className="text-[11px] text-slate-500 mt-1">
                Filters: {appliedFilters.map(([k, v]) => `${k}=${v}`).join(', ')}
              </p>
            )}
            <p className="text-[11px] font-semibold text-slate-600 dark:text-slate-300 mt-1">{result.summary}</p>
          </div>
        </div>

        <div className="flex flex-col items-end gap-2 no-print">
          <ReportExport
            reportCode={result.report.code}
            reportName={result.report.name}
            filters={filters}
            allowedFormats={definition?.allowedFormats}
          />
          <button onClick={onGenerateAgain} className="text-[11px] font-semibold text-indigo-600 hover:underline">
            Generate Again
          </button>
        </div>
      </div>

      {result.rows.length === 0 ? (
        <p className="text-xs text-slate-500 text-center py-10">No data found for the selected filters.</p>
      ) : (
        <ReportTable columns={result.columns} rows={result.rows} />
      )}
    </div>
  );
};

export default ReportPreview;
